-- --- the chain's grammar ------------------------------------------------------------
select pg_temp.must_reject(
  pg_temp.snapshot_stmt('{}'::jsonb),
  'a chain is an array',
  'resolution_snapshots_chain_shape');

select pg_temp.must_reject(
