select pg_temp.must_reject(
  $$update ouroboros.pr_merge_plans
       set merged_result = jsonb_set(merged_result, '{identity_used}', '"pat:someone-else"')
     where id = 'a58c0000-0000-0000-0000-000000000514'$$,
  'and so is who it merged as', 'pr_merge_plans_merged_final');

-- --- every arm, disarm, edit and merge wrote an audit row ---------------------------------------------
select pg_temp.must_hold(
  -- By count: one transaction gives every row the same occurred_at.
  (select array_agg(action order by action)
          = array['pr_merge_plan.armed', 'pr_merge_plan.armed', 'pr_merge_plan.disarmed',
                  'pr_merge_plan.edited', 'pr_merge_plan.edited', 'pr_merge_plan.merged']
     from ouroboros.audit_events
    where subject_type = 'pr_merge_plan' and subject_id = 'a58c0000-0000-0000-0000-000000000514'
      and organization_id = 'org-v058'),
  'the plan''s trail: two edits, arm, disarm, re-arm, merge');

select pg_temp.must_hold(
  (select actor_id = 'a5800000-0000-0000-0000-00000000000a'
          and detail ->> 'revision_id' = 'a58b0000-0000-0000-0000-000000000002'
     from ouroboros.audit_events
    where subject_id = 'a58c0000-0000-0000-0000-000000000514' and action = 'pr_merge_plan.armed'
      and detail ->> 'revision_id' = 'a58b0000-0000-0000-0000-000000000002'),
  'the arm row names who armed and the revision');

select pg_temp.must_hold(
  (select actor_id is null and (detail ->> 'recheck_failed')::boolean
          and detail ->> 'revision_id' = 'a58b0000-0000-0000-0000-000000000002'
          and not (detail ? 'disarm_reason')
     from ouroboros.audit_events
    where subject_id = 'a58c0000-0000-0000-0000-000000000514' and action = 'pr_merge_plan.disarmed'),
  'a re-check''s disarm has no person behind it, and says so');

select pg_temp.must_hold(
  -- V064 (#360): the merged row names updated_by — here still the person of the edits above.
  (select actor_id = 'a5800000-0000-0000-0000-00000000000a' and detail ->> 'sha' = '9a1f0c2'
          and detail ->> 'identity_used' = 'pat:ken-token'
          and detail -> 'actions_executed' = '["close_ticket", "comment_evidence", "delete_branch"]'
          and (detail ->> 'was_armed')::boolean
          and detail ->> 'armed_revision_id' = 'a58b0000-0000-0000-0000-000000000003'
     from ouroboros.audit_events
    where subject_id = 'a58c0000-0000-0000-0000-000000000514' and action = 'pr_merge_plan.merged'),
  'the merge row records what landed, as whom, what ran and what it was armed against');

-- A manual disarm on #88 names the person.
insert into ouroboros.pr_revisions (id, pr_id, revision_seq, head_sha, pushed_at) values
  ('a58b0000-0000-0000-0000-000000000088', 'a58a0000-0000-0000-0000-000000000088', 1, 'e1f2a3b',
   now() - interval '3 minutes');

update ouroboros.pr_merge_plans
   set armed = true, armed_at = now(), armed_by = 'a5800000-0000-0000-0000-00000000000a',
       armed_against_revision_id = 'a58b0000-0000-0000-0000-000000000088'
 where id = 'a58c0000-0000-0000-0000-000000000088';

update ouroboros.pr_merge_plans
   set armed = false, armed_by = null, armed_at = null, armed_against_revision_id = null,
       updated_by = 'a5800000-0000-0000-0000-00000000000a'
 where id = 'a58c0000-0000-0000-0000-000000000088';

select pg_temp.must_hold(
  (select actor_id = 'a5800000-0000-0000-0000-00000000000a' and not (detail ->> 'recheck_failed')::boolean
     from ouroboros.audit_events
    where subject_id = 'a58c0000-0000-0000-0000-000000000088' and action = 'pr_merge_plan.disarmed'),
  'a manual disarm names the person who disarmed');

-- --- grants ---------------------------------------------------------------------------------------------
select pg_temp.must_hold(
  has_table_privilege('ouroboros_app', 'ouroboros.pr_merge_plans', 'select')
   and has_table_privilege('ouroboros_app', 'ouroboros.pr_merge_plans', 'insert')
   and has_table_privilege('ouroboros_app', 'ouroboros.pr_merge_plans', 'update')
   and not has_table_privilege('ouroboros_app', 'ouroboros.pr_merge_plans', 'delete')
   and has_function_privilege('ouroboros_app', 'ouroboros.pr_merge_commit_message_template(uuid)', 'execute')
   and has_function_privilege('ouroboros_app', 'ouroboros.pr_merge_closes_trailer(uuid)', 'execute')
   and not (select bool_or(prosecdef) from pg_proc
             where pronamespace = 'ouroboros'::regnamespace and proname like 'pr_merge_%'),
  'a plan is written and updated but never deleted, and nothing in V058 runs as its owner');

-- The trail is written as the application too: arm, disarm and merge under ouroboros_app.
set local role ouroboros_app;

update ouroboros.pr_merge_plans
   set armed = true, armed_at = now(), armed_by = 'a5800000-0000-0000-0000-00000000000a',
       armed_against_revision_id = 'a58b0000-0000-0000-0000-000000000088'
 where id = 'a58c0000-0000-0000-0000-000000000088';

update ouroboros.pr_merge_plans
   set armed = false, armed_by = null, armed_at = null, armed_against_revision_id = null,
       merged_result = '{"sha": "0badc0d", "identity_used": "pat:ken-token", "actions_executed": ["close_ticket"], "merged_at": "2026-09-24T15:00:00Z"}'
 where id = 'a58c0000-0000-0000-0000-000000000088';

select pg_temp.must_raise(
  $$delete from ouroboros.pr_merge_plans where id = 'a58c0000-0000-0000-0000-000000000088'$$,
  '42501', 'the application cannot delete a plan');

reset role;

select pg_temp.must_hold(
  (select count(*) filter (where action = 'pr_merge_plan.armed') = 2
          and count(*) filter (where action = 'pr_merge_plan.merged') = 1
     from ouroboros.audit_events
    where subject_id = 'a58c0000-0000-0000-0000-000000000088'),
  'the application role''s arm and merge left their audit rows');

-- --- lifecycles -------------------------------------------------------------------------------------------
delete from ouroboros."user" where "id" = 'a5800000-0000-0000-0000-00000000000a';

select pg_temp.must_hold(
  (select count(*) = 2 from ouroboros.pr_merge_plans
    where pr_id in ('a58a0000-0000-0000-0000-000000000514', 'a58a0000-0000-0000-0000-000000000088')
      and updated_by is null)
  and (select count(*) = 0 from ouroboros.audit_events
        where subject_type = 'pr_merge_plan' and actor_id = 'a5800000-0000-0000-0000-00000000000a'),
  'removing a person releases their name from merged plans and the trail, and keeps both');

delete from ouroboros.pull_requests where id = 'a58a0000-0000-0000-0000-000000000514';

select pg_temp.must_hold(
  (select count(*) = 0 from ouroboros.pr_merge_plans where id = 'a58c0000-0000-0000-0000-000000000514')
  and (select count(*) > 0 from ouroboros.audit_events
        where subject_id = 'a58c0000-0000-0000-0000-000000000514'),
  'a PR takes its plan with it, and the audit trail outlives both');

-- --- teardown ---------------------------------------------------------------------------------------------
delete from ouroboros.organization where "id" in ('org-v058', 'org-v058b');

select pg_temp.must_hold(
  (select count(*) = 0 from ouroboros.pr_merge_plans where id::text like 'a58c0000-%')
  and (select count(*) = 0 from ouroboros.audit_events where organization_id like 'org-v058%'),
  'and the V058 fixture leaves nothing behind');

-- ===========================================================================
-- V059 — the coverage summary on a coverage artifact, and the per-attempt delta (#328, AS.5)
-- ===========================================================================
--
-- Mockup 11's `coverage 87.4% (+0.6%)`, as arithmetic. A coverage artifact carries the two
-- counts its report parses to and nothing derived from them; `test_run_coverage` divides, and
-- takes the delta against the previous attempt of the same run that has coverage. Asserted: the
-- counts are required exactly on a coverage artifact and are sane; the view reproduces 86.8%,
-- 87.4% and +0.6 from counts alone; a first attempt has no delta; a tombstone still counts;
-- the counts are frozen with the file; and the app role may read the view.
insert into ouroboros.organization ("id", "name", "slug", "createdAt") values
  ('org-v059', 'Coverage Works', 'coverage-works', now());

insert into ouroboros.github_orgs (id, organization_id, login, enabled) values
  ('a5910000-0000-0000-0000-00000000000a', 'org-v059', 'coverage-works', true);

insert into ouroboros.github_repos (id, org_id, name, enabled, default_branch) values
  ('a591f000-0000-0000-0000-00000000000a', 'a5910000-0000-0000-0000-00000000000a',
   'helios-firmware', true, 'main');

insert into ouroboros.runs
    (id, organization_id, github_repo_id, issue_number, issue_title, workflow_tag,
     model, status, stage_label, stage_index, stage_total, started_at)
  values ('a5920000-0000-0000-0000-000000000482', 'org-v059', 'a591f000-0000-0000-0000-00000000000a',
          482, 'Fix flaky CAN-bus telemetry test', 'standard-fix', 'claude-fable-5',
          'building', 'Test', 6, 8, now() - interval '1 hour');

insert into ouroboros.test_runs (id, organization_id, run_id, attempt_seq, status, started_at) values
  ('a5930000-0000-0000-0000-000000004821', 'org-v059', 'a5920000-0000-0000-0000-000000000482', 1, 'complete', now() - interval '50 minutes'),
  ('a5930000-0000-0000-0000-000000004822', 'org-v059', 'a5920000-0000-0000-0000-000000000482', 2, 'complete', now() - interval '30 minutes'),
  ('a5930000-0000-0000-0000-000000004823', 'org-v059', 'a5920000-0000-0000-0000-000000000482', 3, 'running',  now() - interval '10 minutes');

-- --- the counts are required exactly on a coverage artifact, and sane -------------------------
select pg_temp.must_reject(
  $$insert into ouroboros.test_artifacts
      (organization_id, test_run_id, name, kind, size_bytes, storage_ref, checksum, retained_until)
    values ('org-v059', 'a5930000-0000-0000-0000-000000004822', 'coverage.info', 'coverage', 100,
            '{"driver": "local", "key": "k"}', 'sha256:' || repeat('a', 64), now() + interval '30 days')$$,
  'a coverage artifact carries the counts its report parsed to', 'test_artifacts_coverage_counts');

select pg_temp.must_reject(
  $$insert into ouroboros.test_artifacts
      (organization_id, test_run_id, name, kind, size_bytes, storage_ref, checksum, retained_until,
       lines_covered, lines_total)
    values ('org-v059', 'a5930000-0000-0000-0000-000000004822', 'junit.xml', 'junit', 100,
            '{"driver": "local", "key": "k"}', 'sha256:' || repeat('a', 64), now() + interval '30 days',
            1, 2)$$,
  'and only a coverage artifact carries them', 'test_artifacts_coverage_counts');

select pg_temp.must_reject(
  $$insert into ouroboros.test_artifacts
      (organization_id, test_run_id, name, kind, size_bytes, storage_ref, checksum, retained_until,
       lines_covered, lines_total)
    values ('org-v059', 'a5930000-0000-0000-0000-000000004822', 'coverage.info', 'coverage', 100,
            '{"driver": "local", "key": "k"}', 'sha256:' || repeat('a', 64), now() + interval '30 days',
            6, 5)$$,
  'a report cannot cover more lines than it instruments', 'test_artifacts_coverage_counts_sane');

select pg_temp.must_reject(
  $$insert into ouroboros.test_artifacts
      (organization_id, test_run_id, name, kind, size_bytes, storage_ref, checksum, retained_until,
       lines_covered, lines_total)
    values ('org-v059', 'a5930000-0000-0000-0000-000000004822', 'coverage.info', 'coverage', 100,
            '{"driver": "local", "key": "k"}', 'sha256:' || repeat('a', 64), now() + interval '30 days',
            0, 0)$$,
  'an empty report has no percentage, so it is refused rather than read as zero',
  'test_artifacts_coverage_counts_sane');

-- --- the view divides: 86.8% on Build 2, 87.4% (+0.6) on Build 3 -------------------------------
--
-- Build 3's report is split in two, as a per-module report would be — the attempt's coverage is
-- the sum, not either file's. Build 1 has no coverage at all.
insert into ouroboros.test_artifacts
    (id, organization_id, test_run_id, name, kind, size_bytes, storage_ref, checksum,
     retained_until, lines_covered, lines_total)
  values
    ('a59b0000-0000-0000-0000-000000000002', 'org-v059', 'a5930000-0000-0000-0000-000000004822',
     'coverage.info', 'coverage', 90112, '{"driver": "local", "key": "org-v059/482/2/coverage.info"}',
     'sha256:' || repeat('b', 64), now() + interval '30 days', 4444, 5120),
    ('a59b0000-0000-0000-0000-000000000031', 'org-v059', 'a5930000-0000-0000-0000-000000004823',
     'coverage-drivers.info', 'coverage', 50112, '{"driver": "local", "key": "org-v059/482/3/a"}',
     'sha256:' || repeat('c', 64), now() + interval '30 days', 2475, 2820),
    ('a59b0000-0000-0000-0000-000000000032', 'org-v059', 'a5930000-0000-0000-0000-000000004823',
     'coverage-app.info', 'coverage', 40112, '{"driver": "local", "key": "org-v059/482/3/b"}',
     'sha256:' || repeat('d', 64), now() + interval '30 days', 2000, 2300);

select pg_temp.must_hold(
  (select array_agg(format('%s:%s:%s:%s', attempt_seq, percent,
                           coalesce(previous_attempt_seq::text, '-'), coalesce(delta::text, '-'))
                    order by attempt_seq)
     from ouroboros.test_run_coverage
    where run_id = 'a5920000-0000-0000-0000-000000000482')
    = array['2:86.8:-:-', '3:87.4:2:0.6'],
  'Build 2 covers 86.8% with nothing to compare against, and Build 3 covers 87.4% — +0.6 against Build 2, summed over both of its reports');

-- The delta is taken from the ratios and rounded once, not from two rounded percentages.
select pg_temp.must_hold(
  (select delta = round(100.0 * 4475 / 5120 - 100.0 * 4444 / 5120, 1)
     from ouroboros.test_run_coverage where test_run_id = 'a5930000-0000-0000-0000-000000004823'),
  'the delta is the difference of the unrounded ratios, rounded once');

-- --- a tombstone still counts; the counts are frozen ------------------------------------------
update ouroboros.test_artifacts set expired_at = now()
 where id = 'a59b0000-0000-0000-0000-000000000002';

select pg_temp.must_hold(
  (select percent = 86.8 from ouroboros.test_run_coverage
    where test_run_id = 'a5930000-0000-0000-0000-000000004822'),
  'an expired coverage report still states what it measured — expiry deletes the bytes, not the fact');

select pg_temp.must_reject(
  $$update ouroboros.test_artifacts set lines_covered = 4500
     where id = 'a59b0000-0000-0000-0000-000000000031'$$,
  'a report''s counts describe the uploaded file and are frozen with it', 'test_artifacts_frozen');

select pg_temp.must_hold(
  has_table_privilege('ouroboros_app', 'ouroboros.test_run_coverage', 'select'),
  'the application role reads the coverage view');

delete from ouroboros.organization where "id" = 'org-v059';

-- ===========================================================================
-- V060 — the job-scoped artifact upload: token ledger, receipt and globs (#330, AT.2)
-- ===========================================================================
--
-- Results leave a runner by a job-scoped HTTPS upload rather than the control socket (decision
-- T4). A build job has one ledger row: the hash of the single-use token minted with its offer,
-- then — once the upload is accepted — the receipt: the attempt it filled, the manifest of every
-- file collected (truncated and skipped ones with their reasons) and the job warnings. Asserted:
-- the globs are relative and bounded on the pool and the job; a ledger belongs to a job of its
-- own workspace; a token is stored as a hash; an open ledger holds no receipt and a closed one
-- always does; a re-offer re-mints an open ledger; a closed receipt is final; deleting the
-- attempt clears only its reference; and the app role mints and closes but never deletes.
insert into ouroboros.organization ("id", "name", "slug", "createdAt") values
  ('org-v060',  'Upload Works',       'upload-works',       now()),
  ('org-v060b', 'Other Upload Works', 'other-upload-works', now());

