  values
    ('a6320000-0000-0000-0000-000000000482', 'org-v063', 'a631f000-0000-0000-0000-00000000000a',
     482, 'Fix flaky CAN-bus telemetry test', 'standard-fix', 'claude-fable-5',
     'building', 'Test', 6, 8, now() - interval '1 hour');

