  'a malformed issue_filter is refused: ' || doc, 'playbooks_issue_filter_typed')
  from (values ('{}'),
               ('[]'),
               ('{"label": ["dependencies"]}'),
               ('{"labels": []}'),
               ('{"labels": "dependencies"}'),
               ('{"repos": ["not-a-repo"]}'),
               ('{"repos": ["acme/../etc"]}')) as p(doc);

