  'intervention_cause_rules_signal_known');

select pg_temp.must_reject(
  $$insert into ouroboros.intervention_cause_rules (rule_id, priority, signal, cause, description)
    values ('v079-tie', 50, 'class:test_update', 'other', 'x')$$,
