       ('3f9a2c41d07e88b1',                 '{sample_refs}',       null),
       ('3f9a2c41d07e88b1',                 '{x}',                 '{"share": 7.2}'),
       ('3f9a2c41d07e88b1',                 '{x}',                 '{"count": 0}'),
