   'a8600011-0000-4000-8000-000000000001', 'refs/heads/main', 'zephyr build', 'capped', 'shell',
   'west build', 'queued', 65536),
  ('a8600004-0000-4000-8000-000000000002', 'org-v086', 2, 'a8600001-0000-4000-8000-000000000001',
