select pg_temp.must_reject(
  $$insert into ouroboros.copilot_messages (organization_id, session_id, role, body, tool_trace) values
    ('org-v107', 'a1070000-0000-0000-0000-000000000201', 'copilot', 'x', '{"operations": []}')$$,
