    where workflow_id = 'a1100000-0000-0000-0000-000000000101' and base_version = 1)
   and not exists (select 1 from ouroboros.workflow_draft_replay_mismatches
                    where workflow_id = 'a1100000-0000-0000-0000-000000000101'),
